const __aivicBundle_10_recordReportMetadata = (() => {
  function recordReportMetadata(input: ReportMetadataInput): ReportMetadataRecord {
    if (input["updatedAt"] === undefined || input["updatedAt"] === null) { throw new Error("updatedAt is required"); }
    if (input["createdBy"] === undefined || input["createdBy"] === null) { throw new Error("createdBy is required"); }
    const metadataId = randomUUID();
    const recordedAt = new Date().toISOString();
    
    let isEncrypted = false;
  
    if (input.changeHistory && input.changeHistory.length > 0) {
      for (const entry of input.changeHistory) {
        if (entry.previousValue || entry.newValue) {
          const fieldType = entry.fieldName === "issuesAndConcerns" 
            ? "issue_content" 
            : "personal_info";
          
          if (entry.previousValue) {
            encryptSensitiveField({
              plainText: entry.previousValue,
              fieldType: fieldType,
            });
          }
          
          if (entry.newValue) {
            encryptSensitiveField({
              plainText: entry.newValue,
              fieldType: fieldType,
            });
          }
          
          isEncrypted = true;
        }
      }
    }
  
    return {
      metadataId: metadataId,
      reportId: input.reportId,
      submittedAt: input.submittedAt,
      recordedAt: recordedAt,
      isEncrypted: isEncrypted,
    };
  }
  return { recordReportMetadata };
})();
