const __aivicBundle_11_identifyReportsForArchival = (() => {
  function identifyReportsForArchival(
    input: ArchivalIdentificationInput
  ): ArchivalIdentificationResult {
    const { referenceDateTime, archivalThresholdDays, teamIdFilter } = input;
  
    // Calculate the cutoff date: reports older than this should be archived
    const cutoffDate = new Date(referenceDateTime);
    cutoffDate.setDate(cutoffDate.getDate() - archivalThresholdDays);
  
    // Query reports that are older than the cutoff date
    const queryCondition: ReportQueryConditionInternal = {
      startDate: new Date("1970-01-01"),
      endDate: cutoffDate,
      teamIds: teamIdFilter ? [teamIdFilter] : undefined,
    };
  
    const matchingReports = queryReportsByCondition(queryCondition);
  
    // Extract report IDs and find the oldest report date
    const reportIds = matchingReports.map((report) => report.reportId);
    let oldestReportDate: Date | null = null;
  
    if (matchingReports.length > 0) {
      // Find the oldest report by parsing reportDate strings
      oldestReportDate = matchingReports.reduce((oldest, current) => {
        const currentDate = new Date(current.reportDate);
        return currentDate < oldest ? currentDate : oldest;
      }, new Date(matchingReports[0].reportDate));
    }
  
    return {
      reportIds,
      totalCount: reportIds.length,
      oldestReportDate: oldestReportDate || referenceDateTime,
    };
  }
  
  interface ReportQueryConditionInternal {
    startDate: Date;
    endDate: Date;
    submitterIds?: string[];
    teamIds?: string[];
    statuses?: string[];
    keywordFilter?: string;
  }
  return { identifyReportsForArchival };
})();
